# Bug

Entity A exists - is not New
Entities B and C don't exist - is New
Create valid request data array

``` php
['id'=>1,'bs'=>[0=>['b_attr'=>'sss','_joinData'=>['test'=>'test value']]]]
```

then patch A with BelongsToMany B through C with _joinData for C :

```
$aTable->patchEntity($a, $this->request->data,['bs'=>['associated'=>['_joinData']]]);
```

finally save

```
$aTable->save($a);
```

get Error message:
## All primary key value(s) are needed for updating
# Cause:

function below assumes that if

```
$entity->get($jointProperty)
```

 returns value
then 
`$joint->isNew(false);`

which is not true because patchEntity just created this entity and it is still not saved and it should be new==true

``` php
protected function _collectJointEntities($sourceEntity, $targetEntities) {
        $target = $this->target();
        $source = $this->source();
        $junction = $this->junction();
        $jointProperty = $this->_junctionProperty;
        $primary = (array)$target->primaryKey();

        $result = [];
        $missing = [];

        foreach ($targetEntities as $entity) {
            $joint = $entity->get($jointProperty);

            if (!$joint) {
                $missing[] = $entity->extract($primary);
                continue;
            }

            $joint->isNew(false);
            $result[] = $joint;
        }

        if (empty($missing)) {
            return $result;
        }

        $belongsTo = $junction->association($target->alias());
        $hasMany = $source->association($junction->alias());
        $foreignKey = (array)$this->foreignKey();
        $assocForeignKey = (array)$belongsTo->foreignKey();
        $sourceKey = $sourceEntity->extract((array)$source->primaryKey());

        foreach ($missing as $key) {
            $unions[] = $hasMany->find('all')
                ->where(array_combine($foreignKey, $sourceKey))
                ->andWhere(array_combine($assocForeignKey, $key));
        }

        $query = array_shift($unions);
        foreach ($unions as $q) {
            $query->union($q);
        }

        return array_merge($result, $query->toArray());
    }
```
